    (1, 1301, 'CENTRÍFUGA PARA HUEVO UDTJ-150, ALIMENTACIÓN 110V MONOFÁSICA', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 1285, 1, 2, 1, null, null, null, null, 'UDTJ-150', 'UDTJ-150', null, null, 1300, false, null, false, 0, 'NO', null),
    (1, 1302, 'HORNO DE CONVECCIÓN AMERICAN 6-66X46, SMART 7, ELÉCTRICO 11 KW, 220V. SIN CARRO/SOPORTE (PACKING LIST: "NO INCLUYE SOPORTE")', 1, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 1284, 1, 2, 1, null, null, null, null, 'EX002-A6-A1/1-E-S7-220', 'EX002-A6-A1/1-E-S7-220', null, null, 1301, false, null, false, 0, 'NO', null),
