    (1, 1306, 'DISCO ALETADO PARA QUEMADOR SPARKGAS11 85X26', 1, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0013020039', '0013020039', null, null, 1305, false, null, false, 0, 'NO', null),
    (1, 1307, 'MEZCLADOR COMPLETO PARA QUEMADOR SPARKGAS11', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0013020038', '0013020038', null, null, 1306, false, null, false, 0, 'NO', null),
    (1, 1308, 'TUBERÍA DE SUMINISTRO DE GAS PARA QUEMADOR BTG 11', 3, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0013020074', '0013020074', null, null, 1307, false, null, false, 0, 'NO', null),
    (1, 1309, 'JUNTA TÓRICA (O-RING) OR 2075', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '30294', '30294', null, null, 1308, false, null, false, 0, 'NO', null),
    (1, 1310, 'MIRILLA DE INSPECCIÓN (VIDRIO 20X3) SPARK', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0013010027', '0013010027', null, null, 1309, false, null, false, 0, 'NO', null),
    (1, 1311, 'RACOR DE ACERO INOXIDABLE M5X6', 3, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '58029', '58029', null, null, 1310, false, null, false, 0, 'NO', null),
    (1, 1312, 'TORNILLO DE REGULACIÓN DEL MEZCLADOR BTG', 3, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0013010122', '0013010122', null, null, 1311, false, null, false, 0, 'NO', null),
    (1, 1313, 'RACOR PARA MANGUERA DE GAS BTG 11 DE 3/4"', 3, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0013010105', '0013010105', null, null, 1312, false, null, false, 0, 'NO', null),
    (1, 1314, 'SOPORTE SUPERIOR DEL ELECTRODO', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, null, '53632', null, null, 1313, false, null, false, 0, 'NO', null),
    (1, 1315, 'TRANSFORMADOR DE ENCENDIDO ELECTRÓNICO BRAHMA TD1STPAF', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0005020046', '0005020046', null, null, 1314, false, null, false, 0, 'NO', null),
    (1, 1316, 'CONECTOR (CABLE) PARA MOTOR SPARK L.370', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0005130016', '0005130016', null, null, 1315, false, null, false, 0, 'NO', null),
    (1, 1317, 'ELECTRODO DE IONIZACIÓN BTG 11', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0013020066', '0013020066', null, null, 1316, false, null, false, 0, 'NO', null),
    (1, 1318, 'CONTROLADOR DIGITAL - TEMPERATURA/TIEMPO (INOVA-VERSION 2) LOC', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 558, 1, 2, 4, null, null, null, null, 'ELE-CONT-0041 LOC', 'ELE-CONT-0041 LOC', null, null, 1317, false, null, false, 0, 'NO', null)) as x(loc, codigo, nombre, tipo, clasificacion, estado, estado_orig, minimo, maximo, adm_pm, estante, fila, bloque, proveedor, bodega,
      medida, presentacion, generico, descripcion, cod_prov, visual, codigo_producto, codigo_producto_ant, barras, barras_ant, correlativo, covid, clas_lab, revisado,
      costo, es_generico, foto) loop
    if r.loc <> v_locn then
      select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc; v_locn := r.loc;
    end if;
    if v_loc is null then continue; end if;
    v_cla := null; v_tp := null; v_tpcla := null; v_med := null; v_pre := null; v_prov := null; v_bod := null;
    select id into v_cla from public.clasificaciones_producto where localidad_id = v_loc and codigo_anterior = r.clasificacion;
    select id, clasificacion_id into v_tp, v_tpcla from public.tipos_producto where localidad_id = v_loc and codigo_anterior = r.tipo;
    if v_tp is null then
      if coalesce(r.tipo, 0) <> 0 then v_sintipo := v_sintipo + 1; end if;
    elsif v_cla is null or v_tpcla <> v_cla then
      v_tp := null; v_otra := v_otra + 1;   -- el tipo es de otra clasificación: el producto conserva la suya
    end if;
    select id into v_med from public.tipos_medida where localidad_id = v_loc and codigo_anterior = r.medida;
    select id into v_pre from public.presentaciones_producto where localidad_id = v_loc and codigo_anterior = r.presentacion;
    select id into v_bod from public.bodegas where localidad_id = v_loc and (codigo_anterior = r.bodega or (codigo_anterior is null and codigo = r.bodega)) order by (codigo_anterior = r.bodega) desc nulls last limit 1;
    select id into v_prov from public.proveedores where localidad_id = v_loc and codigo = r.proveedor;
    if v_prov is null and r.proveedor is not null then v_sinprov := v_sinprov + 1; end if;
    v_pm := upper(coalesce(r.adm_pm, '')) = 'S' and coalesce(r.maximo, 0) >= coalesce(r.minimo, 0);

    v_id := null;
    select id into v_id from public.productos where localidad_id = v_loc and codigo_anterior = r.codigo;
    v_cp := r.codigo_producto; v_cb := r.barras;
    if v_cp is not null and exists (select 1 from public.productos where localidad_id = v_loc and upper(codigo_producto) = upper(v_cp) and id is distinct from v_id) then v_cp := null; end if;
    if v_cb is not null and exists (select 1 from public.productos where localidad_id = v_loc and codigo_barras = v_cb and id is distinct from v_id) then v_cb := null; end if;
    if v_id is null then
      if exists (select 1 from public.productos where localidad_id = v_loc and codigo = r.codigo) then
        raise exception 'El código % de la 4-0% lo tiene otro producto: ejecuta primero la parte 1 del script 228.', r.codigo, r.loc;
      end if;
      insert into public.productos (organizacion_id, localidad_id, codigo, nombre, codigo_producto, clasificacion_id, tipo_producto_id, estado, proveedor_id,
        codigo_barras, presentacion_id, tipo_medida_id, generico, punto_minimo, minimo, maximo, precio_costo, estante, fila, bloque, bodega_id, descripcion,
        codigo_anterior, origen_anterior)
      values (v_org, v_loc, r.codigo, r.nombre, v_cp, v_cla, v_tp, r.estado, v_prov,
        v_cb, v_pre, v_med, upper(coalesce(r.es_generico, '')) in ('SI', 'S', 'SÍ'), v_pm, coalesce(r.minimo, 0), coalesce(r.maximo, 0), r.costo, r.estante, r.fila, r.bloque, v_bod, r.descripcion,
        r.codigo, 'MIGRADO')
      returning id into v_id;
      v_n := v_n + 1;
    else
      v_a := v_a + 1;
    end if;
    update public.productos set nombre = r.nombre, codigo_producto = v_cp, clasificacion_id = v_cla, tipo_producto_id = v_tp, estado = r.estado,
      proveedor_id = coalesce(v_prov, proveedor_id), codigo_barras = v_cb, presentacion_id = v_pre, tipo_medida_id = v_med, generico = upper(coalesce(r.es_generico, '')) in ('SI', 'S', 'SÍ'),
      punto_minimo = v_pm, minimo = coalesce(r.minimo, 0), maximo = coalesce(r.maximo, 0), precio_costo = r.costo, estante = r.estante, fila = r.fila,
      bloque = r.bloque, bodega_id = v_bod, descripcion = r.descripcion,
      codigo_anterior = r.codigo, clasificacion_anterior = r.clasificacion, tipo_producto_anterior = r.tipo, tipo_medida_anterior = r.medida, presentacion_anterior = r.presentacion,
      bodega_codigo_anterior = r.bodega, proveedor_codigo_anterior = r.proveedor, estado_original = r.estado_orig, codigo_producto_anterior = r.codigo_producto_ant,
      origen_anterior = 'MIGRADO', codigo_proveedor_anterior = r.cod_prov, codigo_visual = r.visual, administracion_pm = r.adm_pm, correlativo_bodega = r.correlativo,
      covid = r.covid, clasificacion_lab = r.clas_lab, revisado = r.revisado, generico_anterior = r.generico, codigo_barras_anterior = r.barras_ant,
      minimo_anterior = r.minimo, maximo_anterior = r.maximo, es_generico_anterior = r.es_generico, nombre_foto_anterior = r.foto
    where id = v_id;
  end loop;
  raise notice '%', format('Parte 3 de 3: %s productos nuevos, %s actualizados. Sin tipo de producto: %s; con tipo de otra clasificación (se deja sin tipo): %s; con proveedor que no existe: %s.',
    v_n, v_a, v_sintipo, v_otra, v_sinprov);
end;
$migra$;

-- ---------- Precios (ACT_PRECIOS.xlsx, 5): por localidad, producto y tipo de precio (código anterior del tipo de precio). ----------
alter table public.tipos_precio add column if not exists codigo_anterior integer;
alter table public.producto_precios alter column producto_id drop not null;
alter table public.producto_precios add column if not exists localidad_id bigint references public.localidades (id);
alter table public.producto_precios add column if not exists producto_codigo integer;
alter table public.producto_precios add column if not exists fecha timestamptz;
alter table public.producto_precios add column if not exists precio_alterno numeric(18, 4);
alter table public.producto_precios add column if not exists pct_descuento numeric(7, 2);
alter table public.producto_precios add column if not exists estado text not null default 'ACTIVO';
alter table public.producto_precios add column if not exists usuario_ingresa text;
alter table public.producto_precios add column if not exists fecha_ingresa timestamptz;
alter table public.producto_precios add column if not exists usuario_modifica text;
alter table public.producto_precios add column if not exists fecha_modifica timestamptz;
alter table public.producto_precios add column if not exists descuento_aplicado numeric(18, 4);
alter table public.producto_precios add column if not exists pct_utilidad numeric(7, 2);
alter table public.producto_precios add column if not exists precio_base numeric(18, 4);
create unique index if not exists producto_precios_codigo_tipo on public.producto_precios (localidad_id, producto_codigo, tipo_precio_id) where producto_codigo is not null;

do $precios$
declare v_org bigint; v_loc bigint; v_tp bigint; v_prod bigint; v_nuevo boolean; r record; c_n int := 0; c_a int := 0; c_s int := 0;
begin
  select id into v_org from public.organizaciones where codigo::text = '4';
  for r in select * from (values
    (1::integer, 7::integer, 1::integer, '2025-03-03 16:50:44'::timestamp, 10000::numeric, null::numeric, 0::numeric, 'ACTIVO'::text, 'VNR'::text, '2025-03-03 16:50:44'::timestamp, null::text, null::timestamp, 0::numeric, 0::numeric, 0::numeric),
    (1, 7, 2, '2025-03-03 16:51:22', 9500, null, 0, 'ACTIVO', 'VNR', '2025-03-03 16:51:22', null, null, 0, 0, 0),
    (1, 7, 3, '2025-03-03 17:00:55', 9000, null, 0, 'ACTIVO', 'VNR', '2025-03-03 17:00:55', null, null, 0, 0, 0),
    (1, 743, 1, '2024-07-05 14:24:31', 1, null, 0, 'ACTIVO', 'AIA', '2024-07-05 14:24:31', null, null, 0, 0, 0),
    (1, 1013, 1, '2025-05-23 13:35:59', 100, null, 0, 'ACTIVO', '999', '2025-05-23 13:35:59', null, null, 0, 0, 0)) as x(loc, producto, tipo, fecha, precio, alterno, descuento, estado, usr_ing, f_ing, usr_mod, f_mod, aplicado, utilidad, base) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    v_tp := null;
    select id into v_tp from public.tipos_precio where localidad_id = v_loc and coalesce(codigo_anterior, codigo) = r.tipo order by (codigo_anterior = r.tipo) desc nulls last limit 1;
    if v_tp is null then c_s := c_s + 1; continue; end if;
    v_prod := (select id from public.productos where localidad_id = v_loc and codigo_anterior = r.producto);
    insert into public.producto_precios (producto_id, tipo_precio_id, precio, localidad_id, producto_codigo, fecha, precio_alterno, pct_descuento, estado,
      usuario_ingresa, fecha_ingresa, usuario_modifica, fecha_modifica, descuento_aplicado, pct_utilidad, precio_base)
    values (v_prod, v_tp, r.precio, v_loc, r.producto, r.fecha, r.alterno, r.descuento, r.estado, r.usr_ing, r.f_ing, r.usr_mod, r.f_mod, r.aplicado, r.utilidad, r.base)
    on conflict (localidad_id, producto_codigo, tipo_precio_id) where producto_codigo is not null do update set
      producto_id = coalesce(public.producto_precios.producto_id, excluded.producto_id), precio = excluded.precio, fecha = excluded.fecha,
      precio_alterno = excluded.precio_alterno, pct_descuento = excluded.pct_descuento, estado = excluded.estado,
      usuario_ingresa = excluded.usuario_ingresa, fecha_ingresa = excluded.fecha_ingresa, usuario_modifica = excluded.usuario_modifica,
      fecha_modifica = excluded.fecha_modifica, descuento_aplicado = excluded.descuento_aplicado, pct_utilidad = excluded.pct_utilidad,
      precio_base = excluded.precio_base
    returning (xmax = 0) into v_nuevo;
    if v_nuevo then c_n := c_n + 1; else c_a := c_a + 1; end if;
  end loop;
  raise notice '%', format('Precios de la organización 4: %s nuevos, %s actualizados, %s sin tipo de precio (ejecuta antes el script 227).', c_n, c_a, c_s);
end;
$precios$;

notify pgrst, 'reload schema';
